const CASE_STORAGE='dox-erp-cases-v3';
let cases=[],currentCaseId=null,newOCR=null,fileReading=false,newFileInvalid=false,fileToken=0;
const currentCase=()=>cases.find(c=>c.id===currentCaseId);
function persistCases(){const c=currentCase();if(c&&state){c.data=state;c.updatedAt=new Date().toISOString();}try{localStorage.setItem(CASE_STORAGE,JSON.stringify({cases,history,currentCaseId}));return true;}catch{return false;}}
function caseStatus(c){if(!c.data)return {key:'waiting',label:'OCR 업로드 대기'};if(c.data.registered)return {key:'done',label:'등록 시연 완료'};if(pending(c.data).length||problems(c.data).length)return {key:'review',label:'검토 중'};return {key:'ready',label:'등록 준비 완료'};}
function caseNumber(c){return 'CASE-'+c.id.slice(0,8).toUpperCase();}
function makeCase(title,description,type,owner,data){const now=new Date().toISOString();return {id:crypto.randomUUID(),title,description,type,owner,createdAt:now,updatedAt:now,data};}
function syncCurrent(){const c=currentCase();if(c&&state)c.data=state;}
function renderCaseDetail(){const c=currentCase();if(!c)return;const status=caseStatus(c);$('#detailCaseId').textContent=caseNumber(c);$('#detailCaseStatus').textContent=status.label;$('#detailCaseStatus').className='badge case-status '+status.key;$('#detailTitle').textContent=c.title;$('#detailDescription').textContent=c.description||'작성된 업무 내용이 없습니다.';$('#detailMeta').innerHTML=`<span>업무 유형 <b>${esc(c.type)}</b></span><span>담당자 <b>${esc(c.owner||'미지정')}</b></span><span>생성일 <b>${esc(timeText(c.createdAt))}</b></span>`;$('#awaitingOCR').hidden=!!c.data;$('#openUpload').hidden=page!=='register'||!!c.data?.registered;}
function renderCases(){const q=$('#caseSearch').value.trim().toLowerCase(),status=$('#caseStatusFilter').value;const counts={waiting:0,review:0,ready:0,done:0};cases.forEach(c=>counts[caseStatus(c).key]++);$('#caseNavCount').textContent=cases.length;$('#caseListCount').textContent=cases.length;$('#caseMetrics').innerHTML=[['전체 업무 건',cases.length,'생성된 전체 건','▤'],['OCR 업로드 대기',counts.waiting,'결과 파일을 기다리는 건','↥'],['검토·등록 대기',counts.review+counts.ready,'ERP 등록 시연 전','◷'],['등록 시연 완료',counts.done,'시연 이력 저장 완료','✓']].map(([name,count,note,icon],i)=>`<div class="case-metric"><span>${name}<i>${icon}</i></span><strong class="${i===3?'teal-value':''}">${count}<small>건</small></strong><p>${note}</p></div>`).join('');
 const visible=cases.filter(c=>(status==='all'||caseStatus(c).key===status)&&(!q||[caseNumber(c),c.title,c.description,c.owner,c.type,c.data?.filename].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
 $('#caseListBody').innerHTML=visible.length?visible.map(c=>{const s=caseStatus(c);return `<tr><td><small class="case-number">${esc(caseNumber(c))}</small><button class="case-title-link" data-open-case="${c.id}">${esc(c.title)}</button><p class="case-description-text">${esc(c.description||'업무 내용 미작성')}</p></td><td><span class="case-type">${esc(c.type)}</span><div class="case-owner">${esc(c.owner||'담당자 미지정')}</div></td><td>${c.data?`<div class="case-file" title="${esc(c.data.filename)}">▧ ${esc(c.data.filename)}</div><small class="case-file-note">${c.data.rows.length}개 추출 항목 · ${SCHEMA.length}개 ERP 필드</small>`:'<span class="no-file">파일 업로드 전</span>'}</td><td><span class="badge case-status ${s.key}">${s.key==='done'?'✓ ':''}${s.label}</span></td><td class="case-date">${esc(timeText(c.createdAt))}</td><td><button class="case-open" data-open-case="${c.id}">${s.key==='done'?'결과 보기':s.key==='waiting'?'OCR 업로드':'검토하기'} ↗</button></td></tr>`;}).join(''):`<tr><td colspan="6" class="case-empty"><div>▤</div><h3>${cases.length?'조건에 맞는 건이 없습니다.':'첫 번째 업무 건을 생성해 보세요.'}</h3><p>${cases.length?'검색어 또는 진행 상태를 변경해 주세요.':'업무 내용을 작성하고 OCR 결과를 업로드하면 검토와 ERP 등록 시연을 시작할 수 있습니다.'}</p>${cases.length?'':'<button class="button primary" id="emptyCreate">＋ 새 건 생성</button>'}</td></tr>`;
 $('#caseResultCount').textContent=`전체 ${cases.length}건 중 ${visible.length}건 표시`;$('#caseListBody').querySelectorAll('[data-open-case]').forEach(b=>b.onclick=()=>openCase(b.dataset.openCase));if($('#emptyCreate'))$('#emptyCreate').onclick=openCreate;
}
function selectPage(p){syncCurrent();persistCases();if(p==='register'&&!currentCase())p='list';page=p;$('#listPage').hidden=p!=='list';$('#caseDetail').hidden=p!=='register';$('#registerPage').hidden=p!=='register'||!state;$('#historyPage').hidden=p!=='history';$('#backToList').hidden=p!=='register';$('#openUpload').hidden=p!=='register'||!!state?.registered;const title={list:'업무 건을 한곳에서.',register:'OCR 결과를 ERP 데이터로.',history:'등록된 결과를 한눈에.'};const subtitle={list:'건별 업무 내용과 OCR 결과를 관리하고, ERP 등록 진행 상태를 확인하세요.',register:'DOX AI가 추출한 정보를 검토하고 구매·계약 정보로 등록하세요.',history:'DOX AI 추출 결과에서 ERP 등록까지, 시연 이력을 확인하세요.'};$('#pageTitle').textContent=title[p];$('#pageSubtitle').textContent=subtitle[p];$('#breadcrumb').textContent=p==='list'?'업무 건 목록':p==='register'?'업무 건 상세':'등록 이력';document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===(p==='register'?'list':p)));renderCases();renderHistory();if(p==='register')renderCaseDetail();const hash=p==='register'?'#case/'+currentCaseId:p==='history'?'#history':'#cases';if(location.hash!==hash)location.hash=hash;window.scrollTo({top:0,behavior:'smooth'});}
function openCase(id){syncCurrent();const c=cases.find(c=>c.id===id);if(!c){toast('해당 건을 찾을 수 없습니다.');return selectPage('list');}currentCaseId=id;state=c.data;group='project';filter='all';selectedKey='';$('#search').value='';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));if(state)render();selectPage('register');}
function openUploadForCase(){if(!currentCase())return openCreate();if(state?.registered)return toast('등록 시연이 완료된 건입니다. 새 건을 생성해 주세요.');$('#uploadDialog').showModal();}
async function readOCR(file){if(!/\.xlsx?$/i.test(file.name))throw Error('XLSX 또는 XLS 파일을 선택해 주세요.');if(file.size>10*1024*1024)throw Error('10MB 이하의 파일을 선택해 주세요.');return makeState(parseWorkbook(XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false}),file.name));}
function attachOCR(next){const c=currentCase();if(!c)return toast('먼저 건을 생성해 주세요.');if(c.data?.registered)return toast('등록 시연이 완료된 건은 OCR 결과를 교체할 수 없습니다.');const before=c.data;state=next;c.data=next;if(!persistCases()){state=before;c.data=before;return toast('저장 공간이 부족해 OCR 결과를 저장하지 못했습니다.');}$('#uploadDialog').close();openCase(c.id);toast(`${SCHEMA.length}개 OCR 항목을 이 건의 ERP 필드에 자동 입력했습니다.`);}
function clearNewFile(){fileToken++;newOCR=null;newFileInvalid=false;fileReading=false;$('#newCaseFile').value='';$('#newFileName').textContent='Excel 파일을 선택하세요';$('#newFileDescription').textContent='DOX AI OCR 결과 · .xlsx, .xls · 최대 10MB';$('#newFileError').textContent='';$('#submitCreate').disabled=false;$('#removeNewFile').hidden=true;}
function openCreate(){syncCurrent();persistCases();$('#createCaseForm').reset();clearNewFile();$('#createDialog').showModal();$('#newCaseTitle').focus();}
async function chooseNewFile(file){if(!file)return;const token=++fileToken;fileReading=true;newFileInvalid=false;newOCR=null;$('#submitCreate').disabled=true;$('#newFileName').textContent=file.name;$('#newFileDescription').textContent='OCR 결과 확인 중…';$('#newFileError').textContent='';$('#removeNewFile').hidden=false;try{const result=await readOCR(file);if(token!==fileToken)return;newOCR=result;$('#newFileDescription').textContent=`${result.rows.length}개 항목 확인 · 생성 즉시 ERP 필드 자동 입력`;}catch(e){if(token!==fileToken)return;newFileInvalid=true;$('#newFileDescription').textContent='파일을 다시 선택하거나 제외해 주세요.';$('#newFileError').textContent=e.message;}finally{if(token===fileToken){fileReading=false;$('#submitCreate').disabled=false;}}}
function createCase(e){e.preventDefault();const title=$('#newCaseTitle').value.trim();if(!title){$('#newCaseTitle').focus();return toast('건 제목을 입력해 주세요.');}if(fileReading)return toast('파일 확인이 끝날 때까지 기다려 주세요.');if(newFileInvalid)return toast('OCR 결과 파일을 다시 선택하거나 파일 제외를 눌러 주세요.');syncCurrent();const previousId=currentCaseId,previousState=state;const c=makeCase(title,$('#newCaseDescription').value.trim(),$('#newCaseType').value,$('#newCaseOwner').value.trim(),newOCR);cases.unshift(c);currentCaseId=c.id;state=c.data;if(!persistCases()){cases.shift();currentCaseId=previousId;state=previousState;return toast('저장 공간이 부족해 새 건을 생성하지 못했습니다.');}$('#createDialog').close();clearNewFile();openCase(c.id);toast(c.data?'새 건을 생성하고 OCR 결과를 자동 입력했습니다.':'새 건을 생성했습니다. OCR 결과를 업로드해 주세요.');}
async function createSampleCase(){try{const r=await fetch('assets/bid-template.xlsx');if(!r.ok)throw Error('샘플 파일을 불러오지 못했습니다.');const data=makeState(parseWorkbook(XLSX.read(await r.arrayBuffer(),{type:'array'}),'DoxAI_Test01_Bid-Related Documents.xlsx'));data.mode='sample';const c=makeCase('[샘플] '+data.values.project_name,'DOX AI OCR 결과를 검토하고 ERP 구매·계약 등록을 진행하는 시연용 업무 건입니다.','구매·계약','시연 담당자',data);syncCurrent();const previousId=currentCaseId,previousState=state;cases.unshift(c);currentCaseId=c.id;state=data;if(!persistCases()){cases.shift();currentCaseId=previousId;state=previousState;throw Error('저장 공간이 부족합니다.');}openCase(c.id);toast('새 샘플 건을 생성했습니다. 기존 건은 유지됩니다.');}catch(e){toast(e.message);}}
function validData(s){return s&&Array.isArray(s.rows)&&s.reviewed&&SCHEMA.every(f=>s.rows.some(r=>r.label===f.label)&&Object.hasOwn(s.values||{},f.key));}
async function initCases(){let found=false;try{const saved=JSON.parse(localStorage.getItem(CASE_STORAGE));if(saved&&Array.isArray(saved.cases)){cases=saved.cases.filter(c=>c.id&&c.title&&c.createdAt&&(!c.data||validData(c.data)));history=Array.isArray(saved.history)?saved.history.filter(r=>r.id&&validData(r.snapshot)&&r.payload):[];currentCaseId=saved.currentCaseId;state=currentCase()?.data||null;found=true;}else{const legacy=JSON.parse(localStorage.getItem(STORAGE));history=Array.isArray(legacy?.history)?legacy.history.filter(r=>r.id&&validData(r.snapshot)&&r.payload):[];if(validData(legacy?.state)){const c=makeCase(legacy.state.values.project_name||'기존 OCR 검토 건','이전 버전에서 작성한 OCR 검토 내용입니다.','구매·계약','',legacy.state);cases.push(c);currentCaseId=c.id;state=c.data;}for(const r of history){let c=cases.find(c=>c.data?.registered===r.id);if(!c){c=makeCase(r.snapshot.values.project_name||'기존 등록 완료 건','이전 버전에서 저장한 ERP 등록 시연 결과입니다.','구매·계약','',r.snapshot);c.createdAt=r.createdAt;cases.push(c);}if(!r.payload.case_id)r.payload.case_id=c.id;}found=cases.length>0;}}
 catch{toast('저장 데이터를 읽지 못했습니다. 새 건을 생성해 주세요.');}if(!found&&!cases.length){try{const r=await fetch('assets/bid-template.xlsx');if(r.ok){const d=makeState(parseWorkbook(XLSX.read(await r.arrayBuffer(),{type:'array'}),'DoxAI_Test01_Bid-Related Documents.xlsx'));d.mode='sample';cases.push(makeCase('[샘플] '+d.values.project_name,'DOX AI OCR 결과를 검토하고 ERP 등록을 시연하는 예시 건입니다. 상단 생성 버튼으로 실제 시연할 건을 추가하세요.','구매·계약','시연 담당자',d));}}catch{}}
 persistCases();const route=location.hash;if(route.startsWith('#case/'))openCase(route.slice(6));else selectPage(route==='#history'?'history':'list');}
$('#openCreate').onclick=openCreate;$('#backToList').onclick=()=>selectPage('list');$('#detailBack').onclick=()=>selectPage('list');$('#emptyUpload').onclick=openUploadForCase;$('#caseSearch').oninput=renderCases;$('#caseStatusFilter').onchange=renderCases;$('#createCaseForm').onsubmit=createCase;$('#cancelCreate').onclick=()=>$('#createDialog').close();$('#newCaseChoose').onclick=()=>$('#newCaseFile').click();$('#newCaseFile').onchange=e=>chooseNewFile(e.target.files[0]);
const removeFile=document.createElement('button');removeFile.id='removeNewFile';removeFile.type='button';removeFile.className='text-button remove-file';removeFile.textContent='선택한 파일 제외 ×';removeFile.hidden=true;$('#newCaseChoose').after(removeFile);removeFile.onclick=clearNewFile;$('#createDialog').addEventListener('close',()=>{fileToken++;fileReading=false;});
$('#newCaseChoose').ondragover=e=>{e.preventDefault();$('#newCaseChoose').classList.add('dragover');};$('#newCaseChoose').ondragleave=()=>$('#newCaseChoose').classList.remove('dragover');$('#newCaseChoose').ondrop=e=>{e.preventDefault();$('#newCaseChoose').classList.remove('dragover');chooseNewFile(e.dataTransfer.files[0]);};
// Existing close listeners are installed by app.js before this script runs.
document.querySelector('[data-close="createDialog"]').onclick=()=>$('#createDialog').close();
window.addEventListener('hashchange',()=>{const route=location.hash;if(route.startsWith('#case/')){if(page!=='register'||currentCaseId!==route.slice(6))openCase(route.slice(6));}else{const p=route==='#history'?'history':'list';if(page!==p)selectPage(p);}});
initCases();
